describe('Column Visibility Toggle', () => {
    beforeEach(() => {
        cy.visit('/settings'); // Adjust the URL to match your application
    });

    it('should toggle column visibility on happy path', () => {
        cy.get('.settings-menu').click();
        cy.get('.column-toggle').contains('Column A').click(); // Assuming 'Column A' is the column to toggle
        cy.get('.table').should('not.contain', 'Column A'); // Verify that Column A is hidden
        cy.get('.settings-menu').click();
        cy.get('.column-toggle').contains('Column A').click(); // Toggle back to show
        cy.get('.table').should('contain', 'Column A'); // Verify that Column A is visible
    });

    it('should not toggle non-existent column', () => {
        cy.get('.settings-menu').click();
        cy.get('.column-toggle').contains('Non-existent Column').click(); // Attempt to toggle a non-existent column
        cy.get('.notification').should('contain', 'Column not found'); // Verify that an error message is shown
    });
});
